import logging
import re
import socket
from typing import Union

from .tcp import TcpPdu
from ..exceptions import PduConnectionError, BadResponse


class ENICS(TcpPdu):
    """Class provides attributes and private methods to manage a PDU of type ENICS"""

    GET_STATUS_COMMAND = "RELAY:GET:{port}?"
    GET_STATUS_RESPONSE_REGEX = "RELAY:GET:([1-9]|1[0-6]),(OPEN|CLOSE)"
    SET_STATUS_COMMAND = "RELAY:SET:{port}:{status}"
    GET_OUTPUT_VOLTAGE_COMMAND = "OUTPUTVOLTAGE:{port}?"
    GET_CURRENT_COMMAND = "CURRENT:{port}?"
    DEFAULT_PORT = 33330

    def __init__(self, host: str, timeout: Union[float, int] = 20, **kwargs) -> None:
        port = kwargs.get("port", ENICS.DEFAULT_PORT)
        retry_timeout = kwargs.get("retry_timeout", 2.5)
        super().__init__(
            host=host, port=port, timeout=timeout, retry_timeout=retry_timeout
        )

    @property
    def _port_setting(self):
        return {"off": "OPEN", "on": "CLOSE"}

    def _build_command(self, port, status):
        if status:
            return ENICS.SET_STATUS_COMMAND.format(
                port=port, status=self._port_setting[status]
            )
        else:
            return ENICS.GET_STATUS_COMMAND.format(port=port)

    def _parse_response(self, response):
        """Parser for get PDU status response format: RELAY:GET:<outlet>,<state>
        Where <state> can be one of: {OPEN, CLOSE}
        """
        if re.match(ENICS.GET_STATUS_RESPONSE_REGEX, response):
            return response[-5:].strip(",")
        return None

    def get_voltage(self, port: int) -> float:
        """
        the response is of the form OUTPUTVOLTAGE:<channel>:<voltage>
        """
        command = self.GET_OUTPUT_VOLTAGE_COMMAND.format(port=port)
        voltage = self._get_measurement(port, "voltage", command)
        return voltage

    def get_current(self, port: int) -> float:
        """
        the response is of the form CURRENT:<channel>:<value>
        """
        command = self.GET_CURRENT_COMMAND.format(port=port)
        current = self._get_measurement(port, "current", command)
        return current

    def _get_measurement(self, port: int, name: str, command: str) -> float:
        logging.info(f"Fetching {name} value on port: {port}")
        try:
            response = self._execute_cmd_with_retry_on_timeout(command)
            value = float(response.split(":")[-1])
        except socket.error as e:
            logging.error(str(e))
            raise PduConnectionError(f"Error while fetching {name} value on port: {port}")
        except ValueError as e:
            raise BadResponse(str(e))
        return value
